const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const link=(key,label,cls='')=>`<a href="#/${key}" class="${cls}">${label||lookup[key]}</a>`;
const button=(label,cls='orange',key)=>key?link(key,label,`btn ${cls}`):`<button class="btn ${cls}" type="button" data-preview-action="${esc(label)}">${label}</button>`;
const action=(label,ico='arrow',key,cls='orange')=>button(`${label} ${icon(ico)}`,cls,key);
const field=(label,placeholder='',type='text',opts='')=>{let id='field-'+ ++controlIndex;return `<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${esc(label)}" type="${type}" placeholder="${esc(placeholder)}" ${opts}></div>`};
const select=(label,options,placeholder='Select')=>{let id='field-'+ ++controlIndex;return `<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${esc(label)}"><option value="">${placeholder}</option>${options.map(v=>`<option>${v}</option>`).join('')}</select></div>`};
const passwordField=(label='Password',ph='Enter your password')=>{let id='field-'+ ++controlIndex;return `<div class="field"><label for="${id}">${label}</label><div class="password-field"><input id="${id}" type="password" name="${esc(label)}" placeholder="${ph}"><button type="button" data-password-toggle aria-label="Show password">${icon('eye')}</button></div></div>`};
const textArea=(label,ph='')=>{let id='field-'+ ++controlIndex;return `<div class="field"><label for="${id}">${label}</label><textarea id="${id}" placeholder="${ph}"></textarea></div>`};
const tag=(label,kind='green')=>`<span class="tag ${kind}">${label}</span>`;
const panel=(heading,html,subtitle='')=>`<section class="card pad"><div class="panel-title"><h2>${heading}</h2></div>${subtitle?`<p class="muted">${subtitle}</p>`:''}${html}</section>`;
const title=(eyebrow,heading,body='',action='')=>`<div class="section-title"><div>${eyebrow?`<span class="eyebrow">${eyebrow}</span>`:''}<h1>${heading}</h1>${body?`<p>${body}</p>`:''}</div>${action}</div>`;
const stat=(value,label,active=false,ico='car')=>`<div class="stat card ${active?'active':''}"><span class="stat-icon">${icon(ico)}</span><div><strong>${value}</strong><span>${label}</span></div></div>`;
const filters=(names,extra='')=>`<div class="filterbar">${names.map((v,i)=>`<button type="button" data-filter="${v}" class="${i===0?'active':''}">${v}</button>`).join('')}${extra}</div>`;
const table=(heads,rows)=>`<div class="card table-wrap"><table><thead><tr>${heads.map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const row=(name,sub,meta,status,act='',key='')=>`<div class="row"><div><strong>${name}</strong><small>${sub}</small></div><span>${meta}</span>${status}${act?button(act,'light small',key):''}</div>`;
const example='';const logo=`<img class="logo" src="${A}logo.svg" alt="DriveDrop — Vehicle delivery, simplified">`;
const vehicleTypes=['Car','Motorcycle','Van','Classic / prestige','Motorhome / campers','Caravan / trailers','Plant / farm','Other vehicles'];
const transportTypes=['Any','Driven','Open transport','Enclosed transport'];
const carImg=(name='bmw-saloon',cls='vehicle-thumb')=>`<img class="${cls}" src="${A}${name}.webp" alt="${name==='range-rover'?'Range Rover Sport':name==='transit-van'?'Ford Transit Custom':'BMW 3 Series'}">`;
const avatar=(type='driver')=>`<span class="portrait ${type}"><img src="${A}${type==='customer'?'customer-portrait':'transporter-driver'}.webp" alt="Illustrative profile portrait"></span>`;
const stars=`<span class="stars">★★★★★</span>`;
function header(role,key){
 if(role==='Admin')return '';
 const account=['Customer','Transporter'].includes(role);
 const nav=role==='Customer'?[['customer-home','Dashboard'],['customer-request','Get a Quote'],['customer-deliveries','My Deliveries'],['messages','Messages'],['account','Account']]:role==='Transporter'?[['transporter-home','Dashboard'],['transporter-jobs','Find Jobs'],['transporter-active','Deliveries'],['transporter-proceeds','Proceeds'],['transporter-verification','Profile']]:[['how','How It Works'],['customers','For Customers'],['transporters','For Transporters'],['about','About Us'],['help','Help']];
 return `<header class="site-header"><div class="header-inner">${link(account?role.toLowerCase()+'-home':'home',logo,'brand')}<nav aria-label="Main navigation">${nav.map(([k,l])=>link(k,l,k===key?'active':'')).join('')}</nav><div class="header-actions">${account?`${link('notifications',icon('bell')+'<i></i>','notification-link')}${link('account',avatar()+`<span class="user-name">${role==='Customer'?'John Smith':'Tom Davies'}<small>${role}</small></span>`,'account-link')}${link('home',icon('out'),'logout')}`:`${link('login-customer','Log in','login-link')}${action('Get a Quote','arrow','quote')}`}</div></div></header>`;
}
const menuIcons={'Overview':'grid','Quote requests':'file','Your deliveries':'car','Completed':'check','Cancelled':'flag','Messages':'chat','Notifications':'bell','Account':'settings','Available jobs':'search','My submitted quotes':'file','Active deliveries':'truck','Delivered':'check','Booked proceeds':'pound','Verification':'shield','Profile photos':'camera','Reviews':'star','Control Centre':'grid','User management':'user','Transporter verification':'shield','Dispute management':'flag','Bookings & deliveries':'car','Payouts':'pound','Review moderation':'star'};
function shell(role,key,inside){
 const hasRail=role==='Admin'||role==='Customer'&&['customer-home','account'].includes(key);
 const menu=roleMenus[role];
 const rail=hasRail?`<aside class="rail">${role==='Admin'?link('admin-home',`<img src="${A}logo-white.svg" alt="DriveDrop"><small>Admin Portal</small>`,'rail-brand'):''}<nav aria-label="${role} navigation">${menu.map(([k,,name])=>link(k,icon(menuIcons[name]||'file')+name,k===key||key.startsWith('admin-verification')&&k==='admin-verification'||key.startsWith('admin-dispute')&&k==='admin-disputes'?'active':'')).join('')}</nav><div class="rail-bottom">${link(role==='Admin'?'admin-help':'help',icon('help')+'Help & Support')}${link('home',icon('out')+'Sign out')}${role==='Admin'?`<div class="rail-user">${avatar()}<span>Admin User<small>Administrator</small></span></div>`:''}</div></aside>`:'';
 return `<div class="workspace ${hasRail?'with-rail':''} ${role.toLowerCase()}">${rail}<main class="workspace-main">${role==='Admin'?`<div class="admin-top"><div class="search-input">${icon('search')}<input placeholder="Search orders, customers, transporters…" aria-label="Search admin records"></div>${link('notifications',icon('bell'),'notification-link')}</div>`:''}${inside}</main></div>`;
}
function footer(){return `<footer class="footer"><div class="page-width"><div class="footer-grid"><div><img src="${A}logo-white.svg" alt="DriveDrop"><p>Vehicle delivery, simplified.<br>Moving the UK, one vehicle at a time.</p></div><div><h3>Quick Links</h3>${link('how','How It Works')}${link('customers','For Customers')}${link('transporters','For Transporters')}${link('about','About Us')}</div><div><h3>Support</h3>${link('contact','Contact Us')}${link('help','FAQ')}${link('terms','Terms & Conditions')}${link('privacy','Privacy Policy')}</div><div><h3>Your account</h3>${link('login-customer','Customer Login')}${link('login-transporter','Transporter Login')}${link('register-transporter','Join DriveDrop')}</div><div class="coverage">${icon('globe')}<h3>UK Wide Coverage</h3><p>Reliable. Simple. Professional.</p></div></div><div class="footer-bottom"><span>© 2026 DriveDrop. All rights reserved.</span><span>Vehicle delivery, simplified.</span></div></div></footer>`}
function trustStrip(){return `<div class="trust-strip">${[['shield','Transporter verification','Review transporter information.'],['chat','Direct communication','Keep delivery arrangements together.'],['globe','UK wide coverage','Find transport for your journey.']].map(([i,t,d])=>`<div>${icon(i)}<span><strong>${t}</strong><small>${d}</small></span></div>`).join('')}</div>`}
function homepage(){return `<main><section class="home-hero"><div class="page-width hero-copy"><div class="hero-kicker">🇬🇧 &nbsp; UK WIDE COVERAGE</div><h1>The UK’s Smart Way<br>to <em>Deliver Vehicles</em></h1><p>DriveDrop connects you with independent transporters<br>for vehicle delivery across the UK.</p><div class="hero-actions">${action('Get a Quote','arrow','quote')}${action('How It Works','play','how','glass')}</div><div class="hero-benefits"><span>${icon('shield')}Transporter<br>verification</span><span>${icon('chat')}Direct<br>communication</span><span>${icon('globe')}UK Wide<br>Coverage</span></div></div></section>${homeQuoteCard()}<section class="page-width how-section"><span class="eyebrow">HOW DRIVEDROP WORKS</span><h2>Simple. Transparent. Reliable.</h2><div class="steps-grid">${[['file','Get Transport Quotes','Enter your delivery details and receive quotes from independent transporters.'],['hand','Choose Your Transporter','Compare quotes, profiles and reviews. Choose the transporter that best suits your needs.'],['shield','Manage Your Delivery','Agree the details and follow collection and delivery updates in your account.']].map(([i,h,p],n)=>`<article><div class="step-symbol">${icon(i)}<b>${n+1}</b></div><div><h3>${h}</h3><p>${p}</p></div></article>`).join('')}</div><div class="confidence-grid"><div class="card confidence-card">${avatar('customer')}<div><span class="eyebrow">CUSTOMER CONFIDENCE</span><h3>A clear view of your vehicle’s journey.</h3><p>Compare quotes, speak to your transporter and keep your delivery details in one place.</p>${link('customers','Explore the customer experience '+icon('arrow'))}</div></div><div class="coverage-card">${icon('car')}<div><h3>Across the UK</h3><p>One vehicle.<br>One simpler journey.</p></div></div></div></section><section class="page-width transporter-banner"><div><span class="eyebrow">FOR TRANSPORTERS</span><h2>More journeys.<br>One organised workspace.</h2>${action('Join Our Transporter Network','arrow','register-transporter')}</div></section></main>${footer()}`}
function authPage(key){const transporter=key.includes('transporter'),register=key.startsWith('register'),forgot=key==='forgot',reset=key==='reset',admin=key==='login-admin';const heading=forgot?'Forgot your password?':reset?'Reset your password':register?(transporter?'Join Our Transporter Network':'Create Your Account'):admin?'Admin Login':transporter?'Transporter Login':'Customer Login';
 const inputs=forgot?field('Email address','you@example.com','email'):reset?passwordField('New password','Minimum 8 characters')+passwordField('Confirm password','Repeat your new password'):register?field(transporter?'Business / name':'Full name',transporter?'Your business or name':'Your full name')+field('Email address','you@example.com','email')+(!transporter?field('Phone number','Your phone number','tel'):'')+passwordField('Password','Create a password'):field('Email address','you@example.com','email')+passwordField();
 const art=key==='register-transporter'?'transporter-register':key==='login-customer'?'customer-login':transporter?'transporter-driver':register?'customer-portrait':'london-transporter';return `<main class="auth-layout"><section class="auth-card card"><h1>${heading}</h1><p>${register?'Your next journey starts with DriveDrop.':forgot?'Enter your email and we’ll send you a reset link.':reset?'Choose a new password for your account.':'Welcome back! Log in to your account.'}</p><form data-auth-preview>${inputs}${!register&&!forgot&&!reset?`<div class="auth-minor">${link('forgot','Forgot password?')}</div>`:''}<button class="btn orange" type="submit">${register?'Create Account':forgot?'Send Reset Link':reset?'Reset Password':'Log In'} ${icon('arrow')}</button></form>${register?`<p class="legal-small">By creating an account you agree to our ${link('terms','Terms & Conditions')} and ${link('privacy','Privacy Policy')}.</p>`:''}<p class="auth-switch">${register?`Already have an account? ${link(transporter?'login-transporter':'login-customer','Log in')}`:forgot||reset?link('login-customer','Back to login'):`Don’t have an account? ${link(transporter?'register-transporter':'register-customer',transporter?'Apply to become a transporter':'Create an account')}`}</p>${!admin&&!forgot&&!reset?`<div class="role-links">${link(register?'register-customer':'login-customer','Customer',!transporter?'active':'')}${link(register?'register-transporter':'login-transporter','Transporter',transporter?'active':'')}</div>`:''}</section><section class="auth-photo ${key==='register-transporter'||key==='login-customer'?'approved-account-photo':''} ${transporter?'driver-photo':register?'customer-photo':'login-photo'}" style="--photo:url('${A}${art}.webp')"><div><h2>${transporter?'Join Our<br>Transporter Network':register?'A Smoother<br>Way to Move<br>Your Vehicle':'Deliver Vehicles<br>with Confidence'}</h2><ul>${(transporter?['Find suitable transport jobs','Quote on journeys that fit','Manage your deliveries','Keep customers updated']:register?['Request transport quotes','Compare transporter profiles','Manage your bookings','Follow delivery updates']:['Compare transporters','Manage your booking','Stay in touch','UK wide coverage']).map(x=>`<li>${icon('shield')}${x}</li>`).join('')}</ul><p class="photo-signature">${transporter?'Move more with DriveDrop.':'Vehicle delivery, made simple.'}</p></div></section></main>${footer()}`}
let homeExpanded=false;
let quoteStep=1, accountMode='create', quoteDraft={}, calendarMonth=9,calendarYear=2026;
const progress=(labels,current)=>`<div class="progress">${labels.map((x,i)=>`<div class="${i+1===current?'current':i+1<current?'complete':''}"><b>${i+1<current?'✓':i+1}</b><span>${x}</span></div>`).join('')}</div>`;
function dateField(label='Collection date'){return `<div class="field"><label>${label}</label><button type="button" class="date-control" data-date="${label}">${icon('calendar')}<span>${quoteDraft[label]||'Select date'}</span>${icon('calendar')}</button></div>`}
function quoteWorkspace(customerOnly=false){const body=quoteStep===1?panel(`${icon('pin')} Delivery Details`,`<p class="muted">Tell us where your vehicle needs to go.</p><div class="fields">${field('Collection','Enter collection postcode')}${field('Delivery','Enter delivery postcode')}</div>`)+panel(`${icon('calendar')} When would you like collection?`,`<p class="muted">Choose your preferred collection date.</p>${dateField('Collection date')}`):quoteStep===2?panel(`${icon('car')} Vehicle Details`,`<p class="muted">Help transporters understand what needs moving.</p><div class="fields">${select('Vehicle type',vehicleTypes,'Select vehicle type')}${select('Running condition',['Runs and drives','Non-running'],'Select')}${field('Make','Vehicle make')}${field('Model','Vehicle model')}${field('Registration','e.g. AB12 CDE')}</div>`):quoteStep===3?panel(`${icon('truck')} Transport Type`,`<p class="muted">Choose the service you need for your vehicle.</p><div class="transport-options">${transportTypes.map((t,i)=>`<label class="transport-option"><input type="radio" name="Transport type" value="${t}" ${quoteDraft['Transport type']===t?'checked':''}><span class="transport-icon">${icon(i===1?'user':i===0?'globe':'truck')}</span><span><strong>${t}</strong><small>${['Compare suitable transport options','Your vehicle is driven to its destination','Transported on an open carrier','Transported inside an enclosed carrier'][i]}</small></span></label>`).join('')}</div><div id="compatibility" class="notice warn" hidden>Enclosed transport is available for Car, Motorcycle and Classic / prestige. Choose another transport type or change your vehicle type.</div>`):panel('Review your request',`<div class="detail-grid">${['Collection','Delivery','Collection date','Vehicle type','Make','Model','Registration','Running condition','Transport type'].map(k=>`<div class="detail-line"><span>${k}</span><strong>${esc(quoteDraft[k]||'Not specified')}</strong></div>`).join('')}</div>`)+(customerOnly?'':panel('Your customer account',`<div class="role-pills"><button data-account-mode="create" class="${accountMode==='create'?'active':''}">Create account</button><button data-account-mode="login" class="${accountMode==='login'?'active':''}">Login</button></div><div class="fields">${accountMode==='create'?field('Full name','Your full name')+field('Phone number','Your phone number','tel'):''}${field('Email address','you@example.com','email')}${passwordField()}</div><p class="legal-small">${accountMode==='create'?`By creating an account you agree to our ${link('terms','Terms & Conditions')} and ${link('privacy','Privacy Policy')}.`:'Enter your email and password to submit the request to your customer account.'}</p>`));
 return `<div class="quote-workspace">${progress(['Delivery Details','Vehicle Details','Transport Type','Review & Quote'],quoteStep)}<div class="quote-columns"><div class="quote-fields">${body}<p id="quote-error" class="error-message" role="alert"></p><div class="quote-controls"><button class="btn light" data-quote-prev>${icon('back')} Back</button><button class="btn orange" data-quote-next>${quoteStep===4?'Get My Quotes':'Continue'} ${icon('arrow')}</button></div></div><aside class="quote-summary card"><h2>Your Quote</h2><span class="tiny">Step ${quoteStep} of 4</span><div class="orange-rule"></div>${[['pin','Collection'],['pin','Delivery'],['car','Vehicle type'],['truck','Transport type']].map(([i,k])=>`<div class="summary-line">${icon(i)}<div><strong>${k==='Vehicle type'?'Vehicle':k}</strong><small>${esc(quoteDraft[k]||'Not yet specified')}</small></div></div>`).join('')}<div class="summary-help">${icon('pound')}<p>Compare transport quotes<br>in your customer account.</p></div></aside></div>${trustStrip()}</div>`;
}
function publicPage(key){if(key==='home')return homepage();if(key==='quote')return `<main class="page-width">${quoteWorkspace()}</main>${footer()}`;
 if(['terms','privacy'].includes(key)){const content=legalContent[key];return `<main class="legal-layout page-width"><aside class="legal-toc"><h3>On this page</h3>${content.blocks.map((b,i)=>`<button data-section="section-${i}">${b.heading}</button>`).join('')}</aside><article class="legal-copy"><div class="legal-tabs">${link('terms','Terms & Conditions',key==='terms'?'active':'')}${link('privacy','Privacy Policy',key==='privacy'?'active':'')}</div><h1>${lookup[key]}</h1><p class="muted">Last updated: ${content.date}</p>${content.blocks.map((b,i)=>`<section id="section-${i}"><h2>${b.heading}</h2><p>${b.paragraph}</p></section>`).join('')}</article><aside class="legal-promo ${key==='terms'?'terms-photo':''}"><h2>A simpler way<br>to move vehicles<br>across the UK.</h2></aside></main>${footer()}`}
 if(['help','contact'].includes(key))return supportPage(false,key);
 const data={how:['HOW DRIVEDROP WORKS','Simple. Transparent. Reliable.','From your first quote to the final delivery, keep the journey organised.'],customers:['FOR CUSTOMERS','Move Your Vehicle<br>with Confidence','Request quotes, compare transporters and manage the details from one account.'],transporters:['FOR TRANSPORTERS','More journeys.<br>More opportunities.','Find vehicle transport jobs and manage your work with DriveDrop.'],about:['ABOUT DRIVEDROP','Vehicle delivery,<br>simplified.','Connecting vehicle owners and independent transporters across the UK.']}[key];return `<main><section class="public-banner ${key==='transporters'?'driver':''}"><div class="page-width"><span class="eyebrow">${data[0]}</span><h1>${data[1]}</h1><p>${data[2]}</p>${action(key==='transporters'?'Join Our Transporter Network':'Get a Quote','arrow',key==='transporters'?'register-transporter':'quote')}</div></section><section class="page-width marketing"><h2>${key==='transporters'?'Your business. All in one place.':'A clearer journey, from start to finish.'}</h2><div class="feature-grid">${[['file','Request and compare','Enter the journey and vehicle details. Compare quotes, profiles and proposed collection dates.'],['chat','Keep in touch','Discuss arrangements in the booking conversation and keep the details together.'],['shield','Manage the journey','Review collection and delivery reports and confirm receipt from your account.']].map(([i,t,p])=>`<article class="card pad">${icon(i)}<h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section><section class="page-width split marketing"><img src="${A}${key==='transporters'?'transporter-driver':'customer-portrait'}.webp" alt="${key==='transporters'?'Transporter and vehicle carrier':'Customer beside her vehicle'}"><div><span class="eyebrow">BUILT AROUND YOUR JOURNEY</span><h2>${key==='transporters'?'Stay focused on<br>the road ahead.':'Every detail.<br>In one place.'}</h2><p>Quotes, booking information, conversations and delivery updates are connected in your DriveDrop account.</p>${action('Explore your account','arrow',key==='transporters'?'transporter-home':'customer-home')}</div></section></main>${footer()}`}
const deliveryData=[['bmw-saloon','BMW 3 Series','Manchester','London','In Transit','blue'],['range-rover','Range Rover Sport','Birmingham','Edinburgh','Delivered','green'],['transit-van','Ford Transit Custom','Leeds','Birmingham','Quote Received','blue']];
function recentDeliveries(){return `<div class="recent-list">${deliveryData.map(([img,name,from,to,status,colour])=>`<a class="recent-item" href="#/${status==='Delivered'?'customer-completed':'customer-tracking'}">${carImg(img)}<div><strong>${name}</strong><small>${from} → ${to}</small></div><div>${tag(status,colour)}<small>18 October 2026</small></div>${icon('chevron')}</a>`).join('')}</div>`}
function dashboardHero(role){return `<section class="dashboard-hero ${role==='Transporter'?'driver':''}"><div><h1>Welcome back,<br>${role==='Transporter'?'Tom':'John'}!</h1><p>${role==='Transporter'?'Find new transport jobs, manage<br>your deliveries and grow your business<br>with DriveDrop.':'Your vehicle deliveries,<br>simplified.'}</p>${action(role==='Transporter'?'Find Transport Jobs':'Get a New Quote','arrow',role==='Transporter'?'transporter-jobs':'customer-request')}</div></section>`}
function customer(key){if(key==='customer-home')return shell('Customer',key,`${dashboardHero('Customer')}<div class="summary-grid">${stat('3','Active Deliveries',false,'car')}${stat('7','Completed',false,'shield')}${stat('2','Quotes Pending',false,'file')}${stat('0','Cancelled',false,'flag')}</div><div class="columns"><section class="card pad"><div class="panel-title"><h2>Recent Deliveries</h2>${link('customer-deliveries','View All '+icon('arrow'))}</div>${recentDeliveries()}</section>${panel('Quick Actions',`<div class="quick-actions">${[['customer-request','file','Get a New Quote'],['customer-deliveries','car','My Deliveries'],['messages','chat','Message a Transporter'],['customer-requests','file','Manage Quote Requests'],['account','settings','Account Settings']].map(([k,i,l])=>link(k,icon(i)+l+icon('chevron'))).join('')}</div>`)}</div>`);
 if(key==='customer-request')return shell('Customer',key,quoteWorkspace(true));
 if(key==='customer-compare')return shell('Customer',key,`${progress(['Vehicle Details','Quotes','Choose','Confirm'],2)}${title('','Compare Quotes','Compare transporter responses for your delivery route.',select('Sort by',['Price (lowest first)','Price (highest first)','Proposed date'],'Price (lowest first)'))}<div class="quote-comparison">${['SwiftMove Transport','National Auto Logistics','Britannia Vehicle Transport','Direct Car Transport'].map((n,i)=>`<article class="card quote-option"><img src="${A}${i%2?'transporter-driver':'london-transporter'}.webp" alt="Transporter vehicle"><div><h3>${n}</h3><div>${stars} <span class="muted">${['4.9','4.8','4.7','4.6'][i]} · ${[120,84,76,42][i]} reviews</span></div><div class="quote-badges"><span>${icon('shield')}Verification information</span><span>${icon('calendar')}Proposed: ${18+i} October</span></div>${link('public-profile','View transporter profile')}</div><div class="quote-price"><strong>£${[280,320,350,395][i]}</strong><small>Transport quote</small>${button('Choose This Quote '+icon('arrow'),'orange','customer-booking-review')}${button('Message','light small','messages')}</div></article>`).join('')}</div>`);
 if(key==='customer-requests')return shell('Customer',key,`${title('','Quote Requests','Review transporter responses and manage your requests.',action('Get a New Quote','arrow','customer-request'))}${filters(['All Requests','Awaiting Quotes','Quotes Received','Cancelled'])}<div class="delivery-cards">${deliveryData.slice(0,2).map(([img,n,f,t],i)=>`<article class="card delivery-card">${carImg(img)}<div><h3>${n}</h3><p>${icon('pin')}${f} ${icon('arrow')}${t}</p><small>Collection: ${18+i} October · Open transport</small></div><div>${tag(i?'Awaiting Quotes':'3 Quotes Received',i?'amber':'blue')}<div class="button-stack">${button('Compare Quotes','orange','customer-compare')}${button('Cancel Request','light')}</div></div></article>`).join('')}</div>`);
 if(key==='customer-deliveries')return shell('Customer',key,`${title('','Your Deliveries','Manage your bookings from collection to delivery.')}${filters(['All','Scheduled','Collected','In Transit','Awaiting Confirmation'])}<div class="delivery-cards">${deliveryData.slice(0,2).map(([img,n,f,t],i)=>`<article class="card delivery-card">${carImg(img)}<div><h3>${n}</h3><p>${icon('pin')}${f} ${icon('arrow')}${t}</p><small>Collection: ${18+i} October · SwiftMove Transport</small><div class="inline-actions">${button('Message Transporter','navy small','messages')}${button('Call Transporter','light small')}</div></div><div>${tag(i?'Awaiting Confirmation':'In Transit',i?'amber':'blue')}<div class="button-stack">${button(i?'Review Delivery':'View Delivery','orange',i?'customer-confirm':'customer-tracking')}</div></div></article>`).join('')}</div>`);
 if(['customer-tracking','customer-confirm'].includes(key)){const completed=key==='customer-confirm';return shell('Customer',key,`${link('customer-deliveries',icon('back')+' Back to My Deliveries','back-link')}<div class="tracking-title"><div><h1>BMW 3 Series ${tag(completed?'Awaiting Confirmation':'In Transit',completed?'amber':'blue')}</h1><p>${icon('car')} Manchester → London</p><small>Collection date: 18 October 2026</small></div>${carImg()}</div><div class="transporter-identity card"><img src="${A}london-transporter.webp" alt="Transporter carrier"><div><strong>SwiftMove Transport</strong><p>${stars} <span>4.9 (120 reviews)</span></p></div>${button('Message Transporter','light','messages')}${button(icon('phone')+' Call Transporter','light')}</div><div class="delivery-timeline">${['Collection','In Transit','Arriving Soon','Delivered'].map((t,i)=>`<div class="${completed||i<2?'done':''}"><b>${icon('check')}</b><strong>${t}</strong><small>${i===0?'18 Oct · 09:15':completed&&i===3?'18 Oct · 16:20':''}</small></div>`).join('')}</div><div class="columns equal">${panel(completed?'Delivery Evidence':'Journey Details',`${carImg('bmw-saloon','evidence-photo')}<div class="journey-row">${icon('pin')}<span>Manchester<br><small>Collection</small></span>${icon('arrow')}<span>London<br><small>Delivery</small></span></div>${completed?button('View Submitted Report','light','customer-completed'):'<p class="muted tiny">Delivery updates are supplied by your transporter.</p>'}`)}${panel('Delivery Updates',`<ol class="timeline-list"><li><b>${completed?'Vehicle delivered':'Vehicle in transit'}</b><small>18 Oct 2026 · ${completed?'16:20':'14:32'}</small><p>${completed?'Delivery report submitted. Please review and confirm receipt.':'Your vehicle is on the road to London.'}</p></li><li><b>Departed Manchester</b><small>18 Oct 2026 · 10:15</small><p>Vehicle loaded. Collection report recorded.</p></li><li><b>Vehicle collected</b><small>18 Oct 2026 · 09:15</small><p>Collection completed by the transporter.</p></li></ol>`)}</div><div class="form-footer">${button('Report a Problem','light')}${completed?button('Confirm Delivery','orange','customer-completed'):''}</div>`)}
 if(key==='customer-completed')return shell('Customer',key,`${link('customer-deliveries',icon('back')+' Back to My Deliveries','back-link')}<div class="completed-summary">${carImg('range-rover','completed-photo')}<div><h1>Range Rover Sport ${tag('Delivered')}</h1><p>${icon('pin')} Birmingham → Edinburgh</p><p class="success-text">${icon('check')} Delivered on 18 October 2026</p>${table(['Transporter','Collection Date','Delivery Date'],[['National Auto Logistics','17 Oct 2026','18 Oct 2026']])}<div class="detail-line"><span>Total Price</span><strong>£320</strong></div><div class="inline-actions">${button('Leave a Review','orange')}${button('Book Another Delivery','light','customer-request')}</div></div></div><div class="columns equal">${panel('Proof of Delivery',`<div class="proof-grid">${carImg('range-rover','evidence-photo')}${carImg('range-rover','evidence-photo')}</div><p class="tiny muted">Illustrative photo slots. Submitted delivery photos appear here.</p>${button('View Statement','light','statement')}`)}${panel('Your Experience',`<p class="muted">How was your delivery experience?</p><div class="rating-input" aria-label="Rate your delivery">${[1,2,3,4,5].map(n=>`<button data-rating="${n}" aria-label="${n} stars">☆</button>`).join('')}</div>${textArea('Your review','Share your feedback (optional)…')}<div class="form-footer">${button('Submit Review')}</div>`)}</div>`);
 return fallbackCustomer(key);
}
function transporter(key){if(key==='transporter-collection'||key==='transporter-delivery')return reportPage(key==='transporter-delivery');if(key==='transporter-payout-details')return payoutDetailsPage();if(key==='transporter-quote-detail')return submittedQuotePage();if(key==='transporter-home')return shell('Transporter',key,`${dashboardHero('Transporter')}<div class="summary-grid overlap-stats">${stat('24','Quotes Submitted',false,'file')}${stat('6','Active Deliveries',false,'truck')}${stat('£3,480','Booked Proceeds',false,'pound')}${stat('4.8 ★','Your Rating',false,'star')}</div><div class="columns"><section class="card pad"><div class="panel-title"><h2>Recent Activity</h2>${link('notifications','View All '+icon('arrow'))}</div><div class="activity-list">${[['search','New job match available','BMW 3 Series · Manchester to London','2 hours ago','transporter-jobs'],['check','Your quote was accepted','Range Rover Sport · Bristol to Edinburgh','4 hours ago','transporter-active'],['shield','Delivery completed','Ford Transit · Leeds to Birmingham','1 day ago','transporter-completed']].map(([i,t,d,time,k])=>link(k,`<span class="activity-icon">${icon(i)}</span><span><strong>${t}</strong><small>${d}</small></span><small>${time}</small>`)).join('')}</div></section><section class="mini-promo"><h2>More Deliveries.<br>More Opportunities.</h2><p>Find your next journey<br>with DriveDrop.</p>${link('transporter-jobs',`<img src="${A}logo-white.svg" alt="DriveDrop">`)}</section></div>`);
 if(key==='transporter-jobs')return shell('Transporter',key,`${title('','Available Transport Jobs','Find and quote on the latest vehicle transport jobs.')}<div class="card job-filter"><div class="fields four">${field('Collection location','Enter postcode or city')}${field('Delivery location','Enter postcode or city')}${select('Vehicle type',vehicleTypes,'All vehicles')}${select('Transport type',transportTypes,'All transport types')}</div><div class="filter-footer">${button('Clear Filters','light')}<button class="btn orange" data-search-jobs>Search Jobs ${icon('search')}</button></div></div>${filters(['All Jobs','Cars','Vans','Motorcycles','Specialist'])}<div class="job-list">${deliveryData.map(([img,n,f,t],i)=>`<article class="card job-card" data-job-type="${i===2?'Vans':'Cars'}">${carImg(img)}<div class="job-info"><h3>${n}</h3><p>${icon('pin')}${f} ${icon('arrow')}${t}</p><div class="job-meta"><span>${icon('car')}${i===2?'Van':'Car'}</span><span>${icon('calendar')} ${18+i} Oct</span><span>${icon('truck')} Open transport</span></div></div><div class="job-actions">${tag('Open Request','blue')}<button class="btn orange" data-open-quote="${n}">Submit Quote</button></div></article>`).join('')}</div><p class="tiny muted" id="job-result">Showing 3 example requests</p>`);
 if(key==='transporter-quotes')return shell('Transporter',key,`${title('','My Submitted Quotes','View and track the status of your quotes.')}${filters(['All (6)','Pending (3)','Accepted (2)','Not Successful (1)'])}${table(['Vehicle','Route','Your Quote','Status','Date','Actions'],[...deliveryData,...deliveryData].map(([img,n,f,t],i)=>[`${carImg(img)}<strong>${n}</strong>`,`${f} → ${t}`,`<strong>£${[320,480,210,350,290,260][i]}</strong>`,tag(['Pending','Accepted','Not Successful'][i%3],['amber','green','red'][i%3]),`${12+i} Oct 2026`,button('View','light small','transporter-quote-detail')]))}<div class="info-band">${icon('bell')}<span><strong>Keep track of customer responses</strong><small>Quote updates and customer messages appear in your account.</small></span></div>`);
 if(key==='transporter-active')return shell('Transporter',key,`${title('','Active Deliveries','Manage your current deliveries from collection to completion.')}${filters(['Active (3)','Upcoming (2)','Completed (18)'])}<div class="delivery-cards">${deliveryData.map(([img,n,f,t],i)=>`<article class="card delivery-card">${carImg(img)}<div><h3>${n}</h3><p>${icon('pin')} ${f} ${icon('arrow')} ${t}</p><small>${icon('calendar')} Collection: ${18+i} Oct · ${icon('truck')} Open transport</small><div class="inline-actions">${button('Message Customer','navy small','messages')}${button('Call Customer','light small')}</div></div><div>${tag(i===0?'In Transit':i===1?'Collected':'Awaiting Collection',i===2?'amber':'blue')}<div class="button-stack">${button(i===2?'Complete Collection':'Complete Delivery','orange',i===2?'transporter-collection':'transporter-delivery')}<button class="btn light small" data-delivery-details="${n}">View Details</button></div></div></article>`).join('')}</div>`);
 if(key==='transporter-proceeds')return shell('Transporter',key,`${title('','Booked Proceeds','Track your bookings, payment states and financial history.',button('View Statement','light','statement'))}<div class="summary-grid finance-grid">${stat('£4,320','Booked Proceeds',false,'pound')}${stat('£1,050','In Progress',false,'clock')}${stat('£620','Ready for Release',false,'shield')}${stat('£2,650','Paid',false,'check')}</div><div class="columns"><section class="card pad"><div class="panel-title"><h2>Booking Status Overview</h2><div class="chart-legend"><span>Paid</span><span>In progress</span></div></div><div class="bar-chart">${[['May',35,18],['Jun',43,12],['Jul',56,20],['Aug',67,15],['Sep',81,22],['Oct',92,26]].map(([m,h,p])=>`<div><div class="bar-track"><i style="height:${h}%"><b style="height:${p}%"></b></i></div><span>${m}</span></div>`).join('')}</div><p class="tiny muted">Illustrative overview for design review.</p></section>${panel('Recent Payments',`<div class="payment-list">${[620,480,390,350].map((v,i)=>`<div><span class="payment-icon">${icon('pound')}</span><span><strong>£${v}</strong><small>Paid on ${18-i} Oct 2026</small></span>${tag('Paid')}</div>`).join('')}</div>`)}</div><div class="finance-filters">${filters(['All Bookings','Ready for Release','In Progress','Paid','Held'])}${button('Fines / Refunds','light','transporter-adjustments')}</div>${table(['Vehicle','Route','Proceeds','Status','Statement'],deliveryData.map(([img,n,f,t],i)=>[`${carImg(img)}${n}`,`${f} → ${t}`,`£${[280,320,210][i]}`,tag(['In Progress','Ready for Release','Paid'][i],['blue','amber','green'][i]),button('View','light small','statement')]))}`);
 if(key==='transporter-verification')return shell('Transporter',key,`<div class="local-tabs">${link('transporter-verification','Verification','active')}${link('transporter-documents','Insurance')}${link('public-profile','Public Profile')}</div><div class="columns equal"><section class="card pad"><h1>Verification Status</h1><div class="verified-heading">${icon('shield')}<div><h2>Verified Transporter</h2><p>Your example documents have been reviewed.</p></div></div><div class="document-list">${[['file','Driving Licence','Approved'],['shield','Insurance Certificate','Valid until 18 Oct 2027'],['user','Business Details','Complete']].map(([i,n,s])=>`<div>${icon(i)}<span><strong>${n}</strong><small>${s}</small></span>${tag('Verified')}${icon('chevron')}</div>`).join('')}</div><div class="notice success">${icon('shield')}<div><strong>Your documents are up to date</strong><p>Keep your insurance and business information current.</p></div></div>${button('Manage Documents','light','transporter-documents')} ${button('Edit Business Details','light','transporter-business')}</section>${profileCard()}</div>`);
 if(key==='public-profile')return shell('Transporter',key,`${title('','Your Public Transporter Profile','This is how your profile appears to customers.')}<div class="columns equal">${profileCard()}${panel('Customer Reviews',`${stars}<h2>4.8 out of 5</h2><p class="muted">Example profile · 28 reviews</p><div class="review-item"><strong>Clear communication throughout</strong><p>“The collection arrangements were clear and I was kept informed along the way.”</p><small>Example completed booking</small></div>${button('Manage Reviews','light','transporter-reviews')}`)}</div>`);
 if(key==='transporter-profile')return shell('Transporter',key,`${title('','Profile Photos','Add a clear photo of yourself and your vehicle.')}<div class="columns equal">${panel('Your Photo',`${avatar()}${field('Choose profile photo','','file','accept="image/*"')}<div class="form-footer">${button('Choose & Crop Photo','orange')}</div>`)}${panel('Truck Photo',`<img class="profile-truck" src="${A}london-transporter.webp" alt="Transporter truck">${field('Choose truck photo','','file','accept="image/*"')}<div class="form-footer">${button('Choose & Crop Photo','orange')}</div>`)}</div>`);
 if(key==='transporter-business')return fallbackTransporter('transporter-verification');
 return fallbackTransporter(key);
}
